result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-sanitizer/test/sanitize.test.js", "content": "import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';
import he from 'he';
// RED RUN: point at naive.js. GREEN RUN: switch to fixed.js.
import { sanitize } from '../src/naive.js';

/** Recursively collect every element node. */
function allElements(root) {
  const out = [];
  const walk = (node) => {
    if (node.nodeType !== 1) return;
    out.push(node);
    for (const child of node.childNodes) walk(child);
  };
  for (const child of root.childNodes) walk(child);
  return out;
}

/** Fully decode a string (handles named + numeric entities, repeatedly). */
const decode = (s) => he.decode(String(s ?? ''));

/**
 * Assert that `output` contains no executable vector:
 *  - no on* attribute anywhere
 *  - no <script>, <iframe>, <object>, <embed> or <svg> element
 *  - no javascript: scheme after entity decoding (attrs, href/src, text)
 */
function expectNoExecutableVector(output) {
  const root = parse(output);
  const elements = allElements(root);

  // 1. no on-prefixed attribute anywhere (quoted, unquoted, or single-quoted)
  for (const el of elements) {
    for (const [name] of Object.entries(el.attributes)) {
      expect(name.toLowerCase().startsWith('on'), `on* attribute survived: <${el.rawTagName} ${name}=...> in ${JSON.stringify(output)}`).toBe(false);
    }
  }

  // 2. no script/iframe/object/embed/svg elements
  const banned = new Set(['script', 'iframe', 'object', 'embed', 'svg']);
  for (const el of elements) {
    expect(banned.has(el.rawTagName.toLowerCase()), `<${el.rawTagName}> element survived in ${JSON.stringify(output)}`).toBe(false);
  }

  // 3. no javascript: scheme after entity decoding — check every attribute value and all text
  const haystacks = [];
  for (const el of elements) {
    for (const value of Object.values(el.attributes)) haystacks.push(decode(value));
  }
  haystacks.push(decode(root.text));
  for (const h of haystacks) {
    expect(/javascript:/i.test(h.replace(/[\s\x00-\x1f]/g, '')), `javascript: scheme survived: ${JSON.stringify(h)} in ${JSON.stringify(output)}`).toBe(false);
  }
}

describe('sanitize() security contract', () => {
  it('bypass 1: unquoted event handler survives naive regex', () => {
    const output = sanitize('<img src=x onerror=alert(1)>');
    expectNoExecutableVector(output);
  });

  it('bypass 2: single-quoted event handler survives naive regex', () => {
    const output = sanitize("<img src='x' onerror='alert(1)'>");
    expectNoExecutableVector(output);
  });

  it('bypass 3: nested marker reassembles after one removal pass', () => {
    const output = sanitize('<a href="jajavascript:vascript:alert(1)">click</a>');
    expectNoExecutableVector(output);
  });

  it('bypass 4: iframe is not covered by the script-only removal', () => {
    const output = sanitize('<iframe src="javascript:alert(1)" onload="alert(2)"></iframe>');
    expectNoExecutableVector(output);
  });

  it('bypass 5: entity-encoded javascript: scheme evades literal match', () => {
    const output = sanitize('<a href="&#106;avascript:alert(1)">x</a>');
    expectNoExecutableVector(output);
  });
});
"})
