result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-sanitizer/src/fixed.js", "content": "import { parse } from 'node-html-parser';

/**
 * Allowlist sanitizer: parses untrusted HTML and rebuilds it from scratch,
 * emitting only known-safe tags and attributes. Anything not on the allowlist
 * is dropped (dangerous containers entirely, benign unknown tags unwrapped).
 */

const ALLOWED_TAGS = new Set([
  'a', 'p', 'div', 'span', 'br', 'hr', 'b', 'i', 'em', 'strong', 'u', 's',
  'ul', 'ol', 'li', 'blockquote', 'pre', 'code',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'img', 'table', 'thead', 'tbody', 'tr', 'td', 'th',
]);

// Elements whose *contents* must never leak as text either.
const DROP_WITH_CONTENT = new Set([
  'script', 'style', 'iframe', 'object', 'embed', 'svg', 'math',
  'noscript', 'template', 'form', 'base', 'link', 'meta',
]);

const VOID_TAGS = new Set(['br', 'hr', 'img']);

const GLOBAL_ATTRS = new Set(['title']);
const TAG_ATTRS = {
  a: ['href'],
  img: ['src', 'alt'],
};

/** Permit only http(s), mailto, tel, and scheme-less relative URLs.
 *  Input is already entity-decoded by the parser; strip control/whitespace
 *  characters that browsers ignore inside schemes (e.g. "jav\tascript:"). */
function isSafeUrl(raw) {
  const cleaned = String(raw ?? '')
    .replace(/[\s\x00-\x1f\x7f]/g, '')
    .toLowerCase();
  // No scheme at all -> relative URL -> safe.
  if (!/^[a-z][a-z0-9+.\-]*:/.test(cleaned)) return true;
  return /^(https?:|mailto:|tel:)/.test(cleaned);
}

function escapeText(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeAttr(s) {
  return escapeText(s).replace(/"/g, '&quot;');
}

function render(node) {
  // Text node: node-html-parser exposes the decoded text via `.text`;
  // re-escape it so the rebuilt markup is canonical.
  if (node.nodeType === 3) return escapeText(node.text);
  if (node.nodeType !== 1) return ''; // drop comments, directives, etc.

  const tag = node.rawTagName.toLowerCase();

  if (DROP_WITH_CONTENT.has(tag)) return '';
  if (!ALLOWED_TAGS.has(tag)) {
    // Unknown-but-not-dangerous tag: unwrap, keep its children.
    return node.childNodes.map(render).join('');
  }

  const allowed = new Set([...GLOBAL_ATTRS, ...(TAG_ATTRS[tag] ?? [])]);
  let attrs = '';
  for (const [name, value] of Object.entries(node.attributes)) {
    const lower = name.toLowerCase();
    if (!allowed.has(lower)) continue;               // kills every on* handler
    if ((lower === 'href' || lower === 'src') && !isSafeUrl(value)) continue;
    attrs += ` ${lower}="${escapeAttr(value)}"`;
  }

  if (VOID_TAGS.has(tag)) return `<${tag}${attrs}>`;

  const inner = node.childNodes.map(render).join('');
  return `<${tag}${attrs}>${inner}</${tag}>`;
}

export function sanitize(html) {
  const root = parse(String(html ?? ''), { comment: false });
  return root.childNodes.map(render).join('');
}
"})
